def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    # expired, remove it
                    del cache[key]

            if key in cache:
                # still present (not expired), update
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # absent, need to possibly evict
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(v)
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

